        "beatSystemCopy": {
            "saveTheCatTitle": "Save the Cat",
            "saveTheCatDesc": "Nhấn mạnh nhịp cảm xúc rõ ràng và sự tương tác của khán giả.\n\nSử dụng nó khi bạn muốn các bước ngoặt rõ ràng, sự đảo ngược có thể nhìn thấy và cảm giác mạnh mẽ về động lực đối mặt với khán giả từ thiết lập đến đêm chung kết.\n\nTốt nhất cho: tiểu thuyết thương mại, kịch bản, thể loại cao\nCấu hình Momentum: Thiết lập -> Lượt điểm giữa -> Đóng thanh toán",
            "saveTheCatExamples": "Ví dụ: The Hunger Games, The Martian, The Fault in Our Stars.",
            "saveTheCatSourceLabel": "Sách Save the Cat của Jessica Brody",
            "herosJourneyTitle": "Hành trình của anh hùng",
            "herosJourneyDesc": "Theo dõi sự ra đi, chuyển đổi, thử thách và quay trở lại.\n\nSử dụng nó khi bạn muốn có một vòng cung định hướng thần thoại hoặc danh tính với sự biến đổi bên trong và bên ngoài có thể nhìn thấy.\n\nTốt nhất cho: câu chuyện nhiệm vụ, tiểu thuyết đầu cơ, tuổi mới lớn, hành trình biến đổi\nHồ sơ động lực: Khởi hành -> Thử nghiệm -> Thử thách -> Trở về với sự thay đổi",
            "herosJourneyExamples": "Ví dụ: Chiến tranh giữa các vì sao, The Hobbit, A Wizard of Earthsea.",
            "herosJourneySourceLabel": "Christopher Vogler's The Writer's Journey",
            "classicDramaticTitle": "Cấu trúc kịch tính cổ điển",
            "classicDramaticDesc": "Nhấn mạnh áp lực cảnh, bước ngoặt, lựa chọn quan trọng và kết quả hậu quả.\n\nSử dụng nó khi bạn muốn kiểm tra căng thẳng xem mỗi cảnh có tạo ra chuyển động thông qua xung đột và thay đổi hay không.\n\nTốt nhất cho: tiểu thuyết văn học, kịch, tác phẩm cảnh được chỉnh sửa chặt chẽ, thẻ sửa đổi\nHồ sơ Momentum: Thiết lập → Biến chứng → Áp lực → Lựa chọn quan trọng → Kết quả",
            "classicDramaticExamples": "Ví dụ: Niềm tự hào và định kiến, Hamlet, The Godfather.",
            "podcastArcTitle": "Arc tường thuật podcast",
            "podcastArcDesc": "Hình dạng kể chuyện bằng cách nói xung quanh móc, thiết lập, phát triển và phần thưởng.\n\nSử dụng nó khi bạn muốn giữ người nghe mạnh mẽ và tiến trình bằng lời nói rõ ràng.\n\nTốt nhất cho: podcast, tiểu luận âm thanh, độc thoại, truyện phi hư cấu\nHồ sơ Momentum: Hook -> Khung -> Phát triển -> Hoàn trả",
            "podcastArcExamples": "Ví dụ: các tập podcast tường thuật, các tập câu chuyện do phỏng vấn dẫn đầu, phân đoạn âm thanh tài liệu.",
            "youtubeExplainerTitle": "Vòng cung giải thích trên YouTube",
            "youtubeExplainerDesc": "Tổ chức giảng dạy và giải thích xung quanh sự tò mò, rõ ràng và tiến bộ.\n\nSử dụng nó khi bạn muốn người xem hiểu điều gì đó nhanh chóng trong khi duy trì sự tương tác.\n\nTốt nhất cho: người giải thích, video giáo dục, bình luận, hướng dẫn\nHồ sơ Momentum: Hook -> Promise -> Breakdown -> Takeaway",
            "youtubeExplainerExamples": "Ví dụ: người giải thích giáo dục, kênh bình luận, kể chuyện theo hướng dẫn.",
            "documentaryArcTitle": "Arc tường thuật tài liệu",
            "documentaryArcDesc": "Cân bằng thời gian, bối cảnh, cổ phần và hệ quả trong các sự kiện được kể lại.\n\nSử dụng nó khi bạn cần hướng dẫn khán giả thông qua các sự kiện thực tế mà không mất đà.\n\nTốt nhất cho: viết lịch sử, cấu trúc tài liệu, kể chuyện phi hư cấu, dòng thời gian\nHồ sơ động lượng: Bối cảnh -> Xây dựng -> Pivot -> Hậu quả",
            "documentaryArcExamples": "Ví dụ: phim tài liệu lịch sử, các chương lịch sử tường thuật, tái hiện sự kiện.",
            "romanceLadderTitle": "Thang bậc cốt truyện tình yêu",
            "romanceLadderDesc": "Theo dõi sự hấp dẫn, căng thẳng, dễ bị tổn thương, vỡ và phần thưởng cảm xúc.\n\nSử dụng nó khi vòng cung quan hệ tình cảm là động cơ chính của đầu tư của độc giả.\n\nTốt nhất cho: lãng mạn, cốt truyện phụ lãng mạn, nhân vật hóa học\nHồ sơ động lượng: Spark -> Căng thẳng -> Tính dễ bị tổn thương -> Vỡ -> Liên minh / Quyết định",
            "romanceLadderExamples": "Ví dụ: kẻ thù với người yêu, sự gần gũi cưỡng bức, sự cháy chậm.",
            "thrillerLadderTitle": "Thang leo thang kinh dị",
            "thrillerLadderDesc": "Xây dựng áp lực thông qua nguy hiểm, mặc khải, đảo ngược và thu hẹp các lựa chọn.\n\nSử dụng nó khi bạn muốn mọi giai đoạn để thắt chặt rủi ro và giảm sự lựa chọn an toàn của nhân vật chính.\n\nTốt nhất cho: phim kinh dị, hồi hộp, rượt đuổi, câu chuyện sinh tồn\nHồ sơ động lực: Đe dọa -> Theo đuổi -> Đảo ngược -> Nén -> Đối đầu",
            "thrillerLadderExamples": "Ví dụ: Cô gái chạy trốn, Gone Girl, The Silence of the Lambs.",
            "customTitle": "Hệ thống tùy chỉnh",
            "customDesc": "Thiết kế khung cấu trúc của riêng bạn cho bản thảo này. xác định các nhịp quan trọng trong câu chuyện của bạn - cho dù chúng theo dõi một vòng cung cổ điển hay theo dõi tiến trình cụ thể theo thể loại.\n\nHệ thống tùy chỉnh có thể đại diện cho các trò chơi, lượt theo chủ đề, các mốc điều tra, giai đoạn lịch sử hoặc bất kỳ nhịp điệu cấu trúc nào bạn muốn đo lường.",
            "customExamples": "Ví dụ: quy trình làm việc mới lạ tùy chỉnh, hệ thống sửa đổi riêng, cấu trúc lớp học.",
            "blankCustomTitle": "Tùy chỉnh trống",
            "blankCustomDesc": "Bắt đầu trống để bạn có thể thiết kế cấu trúc của riêng mình từ đầu.\n\nSử dụng nó khi không có ống kính thư viện nào phù hợp với quy trình của bạn hoặc bạn muốn một mô hình dành riêng cho dự án.\n\nTốt nhất cho: thiết kế nhịp tùy chỉnh, thử nghiệm, cấu trúc lai, dạy phương pháp của riêng bạn\nHồ sơ động lượng: do tác giả xác định",
            "blankCustomExamples": "Bắt đầu với ít nhất 3 nhịp. Đặt tên cho từng nhịp theo chức năng, không phải chủ đề. Sử dụng một tiến trình rõ ràng như mở -> áp lực -> dịch chuyển. Thêm hoặc Sắp xếp lại chỉ đánh khi mỗi cái phục vụ một mục đích cấu trúc riêng biệt."
        },
