            "glossaryPageBreakTerm": "Ngắt trang",
            "glossaryPageBreakDef": "Khi bật, mọi tiêu đề phần bắt đầu trên một trang mới (`\\cleardoublepage`). Tắt giữ các bộ phận nội tuyến trong văn bản đang chạy.",
